package com.tilemarkersymbols;

import lombok.AllArgsConstructor;
import lombok.Getter;
import net.runelite.api.coords.WorldPoint;

import java.awt.Color;

@Getter
@AllArgsConstructor
class SymbolTileMarker
{
	private final WorldPoint worldPoint;
	private final String label;
	private final Color color;
}

package com.tilemarkersymbols;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("tilemarkersymbols")
public interface TileMarkerSymbolsConfig extends Config
{
	@ConfigSection(
		name = "Favorites",
		description = "Configure favorite Unicode tile marker symbols.",
		position = 0
	)
	String favoritesSection = "favorites";

	@ConfigSection(
		name = "Display",
		description = "Configure plugin display options.",
		position = 1
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "favorites",
		name = "Favorite symbols",
		description = "Symbols to show in the sidebar. Separate symbols with spaces.",
		position = 1,
		section = favoritesSection
	)
	default String favorites()
	{
		return "✓ ✕ ★ ☆ → ← ↑ ↓ ⚠ ⊙ ● ○ ◆ ◇";
	}

	@ConfigItem(
		keyName = "showSidebarPanel",
		name = "Show sidebar panel",
		description = "Shows the Tile Marker Symbols sidebar panel.",
		position = 1,
		section = displaySection
	)
	default boolean showSidebarPanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "markMenuMode",
		name = "Show mark option",
		description = "Configures whether the Mark with Symbol option appears on right-click or only while shift-right-clicking.",
		position = 2,
		section = displaySection
	)
	default MarkMenuMode markMenuMode()
	{
		return MarkMenuMode.RIGHT_CLICK;
	}

	@ConfigItem(
		keyName = "savedMarkers",
		name = "Saved markers",
		description = "Saved symbol tile markers.",
		hidden = true
	)
	default String savedMarkers()
	{
		return "";
	}

	enum MarkMenuMode
	{
		RIGHT_CLICK("Right-click"),
		SHIFT_RIGHT_CLICK("Shift-right-click");

		private final String name;

		MarkMenuMode(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}
}

package com.tilemarkersymbols;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.Stroke;

class TileMarkerSymbolsOverlay extends Overlay
{
	private static final int MAX_DRAW_DISTANCE = 32;

	private static final String GROUND_MARKER_CONFIG_GROUP = "groundMarker";
	private static final String MARKER_COLOR_KEY = "markerColor";
	private static final String BORDER_WIDTH_KEY = "borderWidth";
	private static final String FILL_OPACITY_KEY = "fillOpacity";

	private static final Color DEFAULT_MARKER_COLOR = Color.YELLOW;
	private static final double DEFAULT_BORDER_WIDTH = 2.0;
	private static final int DEFAULT_FILL_OPACITY = 50;

	private final Client client;
	private final ConfigManager configManager;
	private final TileMarkerSymbolsPlugin plugin;

	@Inject
	TileMarkerSymbolsOverlay(
		Client client,
		ConfigManager configManager,
		TileMarkerSymbolsPlugin plugin
	)
	{
		this.client = client;
		this.configManager = configManager;
		this.plugin = plugin;

		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldView worldView = client.getTopLevelWorldView();

		if (worldView == null)
		{
			return null;
		}

		graphics.setRenderingHint(
			RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_ON
		);

		int fillOpacity = getGroundMarkerFillOpacity();
		double borderWidth = getGroundMarkerBorderWidth();

		Stroke stroke = new BasicStroke((float) borderWidth);
		Color fillColor = new Color(0, 0, 0, fillOpacity);

		for (SymbolTileMarker marker : plugin.getMarkers())
		{
			Color markerColor = marker.getColor();

			if (markerColor == null)
			{
				markerColor = getGroundMarkerColor();
			}

			drawTile(graphics, worldView, marker, markerColor, fillColor, stroke);
		}

		return null;
	}

	private void drawTile(
		Graphics2D graphics,
		WorldView worldView,
		SymbolTileMarker marker,
		Color markerColor,
		Color fillColor,
		Stroke stroke
	)
	{
		WorldPoint worldPoint = marker.getWorldPoint();

		if (worldPoint.getPlane() != worldView.getPlane())
		{
			return;
		}

		Player player = client.getLocalPlayer();

		if (player != null && player.getWorldView().isTopLevel())
		{
			WorldPoint playerLocation = player.getWorldLocation();

			if (worldPoint.distanceTo(playerLocation) >= MAX_DRAW_DISTANCE)
			{
				return;
			}
		}

		LocalPoint localPoint = LocalPoint.fromWorld(worldView, worldPoint);

		if (localPoint == null)
		{
			return;
		}

		Polygon tilePolygon = Perspective.getCanvasTilePoly(client, localPoint);

		if (tilePolygon != null)
		{
			OverlayUtil.renderPolygon(
				graphics,
				tilePolygon,
				markerColor,
				fillColor,
				stroke
			);
		}

		String label = marker.getLabel();

		if (label == null || label.isEmpty())
		{
			return;
		}

		Point textLocation = Perspective.getCanvasTextLocation(
			client,
			graphics,
			localPoint,
			label,
			0
		);

		if (textLocation != null)
		{
			OverlayUtil.renderTextLocation(
				graphics,
				textLocation,
				label,
				markerColor
			);
		}
	}

	private Color getGroundMarkerColor()
	{
		Color color = configManager.getConfiguration(
			GROUND_MARKER_CONFIG_GROUP,
			MARKER_COLOR_KEY,
			Color.class
		);

		if (color == null)
		{
			return DEFAULT_MARKER_COLOR;
		}

		return color;
	}

	private double getGroundMarkerBorderWidth()
	{
		Double borderWidth = configManager.getConfiguration(
			GROUND_MARKER_CONFIG_GROUP,
			BORDER_WIDTH_KEY,
			double.class
		);

		if (borderWidth == null)
		{
			return DEFAULT_BORDER_WIDTH;
		}

		return borderWidth;
	}

	private int getGroundMarkerFillOpacity()
	{
		Integer fillOpacity = configManager.getConfiguration(
			GROUND_MARKER_CONFIG_GROUP,
			FILL_OPACITY_KEY,
			int.class
		);

		if (fillOpacity == null)
		{
			return DEFAULT_FILL_OPACITY;
		}

		return Math.max(0, Math.min(255, fillOpacity));
	}
}

package com.tilemarkersymbols;

import net.runelite.client.ui.PluginPanel;

import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.HashMap;
import java.util.Map;

class TileMarkerSymbolsPanel extends PluginPanel
{
	private static final Color SELECTED_BUTTON_COLOR = new Color(70, 70, 70);
	private static final Color NORMAL_BUTTON_COLOR = new Color(35, 35, 35);

	private final TileMarkerSymbolsConfig config;
	private final TileMarkerSymbolsPlugin plugin;
	private final JPanel symbolPanel = new JPanel();
	private final JLabel selectedLabel = new JLabel("No symbol selected", SwingConstants.CENTER);
	private final Map<String, JButton> symbolButtons = new HashMap<>();

	TileMarkerSymbolsPanel(TileMarkerSymbolsConfig config, TileMarkerSymbolsPlugin plugin)
	{
		this.config = config;
		this.plugin = plugin;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

		JLabel title = new JLabel("Tile Marker Symbols", SwingConstants.CENTER);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 18f));
		add(title, BorderLayout.NORTH);

		JPanel centerPanel = new JPanel(new BorderLayout());
		centerPanel.setOpaque(false);

		symbolPanel.setLayout(new GridLayout(0, 4, 6, 6));
		symbolPanel.setBorder(BorderFactory.createEmptyBorder(12, 0, 20, 0));
		centerPanel.add(symbolPanel, BorderLayout.NORTH);

		selectedLabel.setFont(selectedLabel.getFont().deriveFont(Font.BOLD, 18f));
		selectedLabel.setBorder(BorderFactory.createEmptyBorder(18, 0, 20, 0));
		centerPanel.add(selectedLabel, BorderLayout.CENTER);

		JPanel actionPanel = new JPanel(new GridLayout(0, 1, 0, 6));
		actionPanel.setOpaque(false);

		JButton undoButton = new JButton("Undo last marker");
		undoButton.setFocusPainted(false);
		undoButton.addActionListener(e -> plugin.undoLastMarker());
		actionPanel.add(undoButton);

		JButton clearButton = new JButton("Clear all symbol markers");
		clearButton.setFocusPainted(false);
		clearButton.addActionListener(e -> confirmClearAllMarkers());
		actionPanel.add(clearButton);

		centerPanel.add(actionPanel, BorderLayout.SOUTH);

		add(centerPanel, BorderLayout.CENTER);

		rebuild();
	}

	void rebuild()
	{
		symbolPanel.removeAll();
		symbolButtons.clear();

		String favorites = config.favorites();

		if (favorites == null || favorites.trim().isEmpty())
		{
			symbolPanel.add(new JLabel("No symbols configured."));
		}
		else
		{
			String[] symbols = favorites.trim().split("\\s+");

			for (String symbol : symbols)
			{
				JButton button = new JButton(symbol);

				button.setFocusPainted(false);
				button.setPreferredSize(new Dimension(52, 44));
				button.setFont(button.getFont().deriveFont(Font.BOLD, 20f));
				button.setToolTipText("Select and copy " + symbol);
				button.setBackground(NORMAL_BUTTON_COLOR);
				button.setOpaque(true);

				button.addActionListener(e -> selectSymbol(symbol));

				symbolButtons.put(symbol, button);
				symbolPanel.add(button);
			}
		}

		updateSelectedDisplay();

		symbolPanel.revalidate();
		symbolPanel.repaint();
	}

	private void selectSymbol(String symbol)
	{
		plugin.setSelectedSymbol(symbol);
		copyToClipboard(symbol);
		updateSelectedDisplay();
	}

	private void updateSelectedDisplay()
	{
		String selectedSymbol = plugin.getSelectedSymbol();

		for (Map.Entry<String, JButton> entry : symbolButtons.entrySet())
		{
			boolean isSelected = entry.getKey().equals(selectedSymbol);
			entry.getValue().setBackground(isSelected ? SELECTED_BUTTON_COLOR : NORMAL_BUTTON_COLOR);
		}

		if (selectedSymbol == null || selectedSymbol.isEmpty())
		{
			selectedLabel.setText(
				"<html><center>" +
					"Selected Symbol<br>" +
					"<span style='font-size:22px;'>None</span>" +
				"</center></html>"
			);
		}
		else
		{
			selectedLabel.setText(
				"<html><center>" +
					"✓ Selected & Copied<br>" +
					"<span style='font-size:36px;'>" +
						selectedSymbol +
					"</span><br>" +
					"<span style='font-size:11px;'>Right-click a tile to mark it.</span>" +
				"</center></html>"
			);
		}
	}

	private void confirmClearAllMarkers()
	{
		int result = JOptionPane.showConfirmDialog(
			this,
			"Clear all tiles marked with symbols?",
			"Clear symbol markers",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE
		);

		if (result == JOptionPane.YES_OPTION)
		{
			plugin.clearAllMarkers();
		}
	}

	private void copyToClipboard(String text)
	{
		StringSelection selection = new StringSelection(text);
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, null);
	}
}

package com.tilemarkersymbols;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;

import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.stream.Collectors;

@Slf4j
@PluginDescriptor(
	name = "Tile Marker Symbols",
	description = "Provides quick access to Unicode symbols for tile marker labels.",
	tags = {"tile", "marker", "symbols", "labels", "unicode"}
)
public class TileMarkerSymbolsPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "tilemarkersymbols";
	private static final String SAVED_MARKERS_KEY = "savedMarkers";

	private static final String MARK_TILE_OPTION = "Mark with Symbol";
	private static final String CLEAR_TILE_OPTION = "Clear Symbol Marker";
	private static final String LABEL_TILE_OPTION = "Label Symbol Marker";
	private static final String COLOR_TILE_OPTION = "Color Symbol Marker";

	private static final String GROUND_MARKER_CONFIG_GROUP = "groundMarker";
	private static final String GROUND_MARKER_COLOR_KEY = "markerColor";
	private static final Color DEFAULT_MARKER_COLOR = Color.YELLOW;

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TileMarkerSymbolsOverlay overlay;

	@Inject
	private TileMarkerSymbolsConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ColorPickerManager colorPickerManager;

	private final List<SymbolTileMarker> markers = new ArrayList<>();

	private TileMarkerSymbolsPanel panel;
	private NavigationButton navButton;
	private boolean sidebarPanelAdded = false;
	private String selectedSymbol = "";

	@Override
	protected void startUp()
	{
		loadMarkers();

		panel = new TileMarkerSymbolsPanel(config, this);

		navButton = NavigationButton.builder()
			.tooltip("Tile Marker Symbols")
			.icon(createIcon())
			.priority(5)
			.panel(panel)
			.build();

		updateSidebarPanel();

		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		removeSidebarPanel();

		panel = null;
		navButton = null;
		markers.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (panel != null)
		{
			panel.rebuild();
		}

		updateSidebarPanel();
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!shouldShowMarkerMenu())
		{
			return;
		}

		MenuAction menuAction = event.getMenuEntry().getType();

		if (menuAction != MenuAction.WALK && menuAction != MenuAction.SET_HEADING)
		{
			return;
		}

		int worldViewId = event.getMenuEntry().getWorldViewId();
		WorldView worldView = client.getWorldView(worldViewId);

		if (worldView == null)
		{
			return;
		}

		Tile selectedSceneTile = worldView.getSelectedSceneTile();

		if (selectedSceneTile == null)
		{
			return;
		}

		final WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, selectedSceneTile.getLocalLocation());

		if (worldPoint == null)
		{
			return;
		}

		final SymbolTileMarker existingMarker = getMarker(worldPoint);

		if (selectedSymbol != null && !selectedSymbol.isEmpty())
		{
			client.createMenuEntry(-1)
				.setOption(MARK_TILE_OPTION)
				.setTarget("")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> markTile(worldPoint, selectedSymbol));
		}

		if (existingMarker != null)
		{
			client.createMenuEntry(-2)
				.setOption(CLEAR_TILE_OPTION)
				.setTarget("")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> clearMarker(worldPoint));

			client.createMenuEntry(-3)
				.setOption(LABEL_TILE_OPTION)
				.setTarget("")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> labelTile(existingMarker));

			MenuEntry colorMenuEntry = client.createMenuEntry(-4)
				.setOption(COLOR_TILE_OPTION)
				.setTarget("")
				.setType(MenuAction.RUNELITE);

			Menu colorSubMenu = colorMenuEntry.createSubMenu();

			colorSubMenu.createMenuEntry(-1)
				.setOption("Pick")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> openColorPicker(existingMarker));

			colorSubMenu.createMenuEntry(-2)
				.setOption("Reset")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> colorTile(existingMarker, null));

			List<Color> existingColors = markers.stream()
				.map(SymbolTileMarker::getColor)
				.filter(color -> color != null)
				.distinct()
				.collect(Collectors.toList());

			for (Color color : existingColors)
			{
				if (!color.equals(existingMarker.getColor()))
				{
					colorSubMenu.createMenuEntry(-1)
						.setOption(ColorUtil.prependColorTag("Color", color))
						.setType(MenuAction.RUNELITE)
						.onClick(e -> colorTile(existingMarker, color));
				}
			}
		}
	}

	void setSelectedSymbol(String selectedSymbol)
	{
		this.selectedSymbol = selectedSymbol;
	}

	String getSelectedSymbol()
	{
		return selectedSymbol;
	}

	Collection<SymbolTileMarker> getMarkers()
	{
		return markers;
	}

	void undoLastMarker()
	{
		if (markers.isEmpty())
		{
			return;
		}

		markers.remove(markers.size() - 1);
		saveMarkers();
	}

	void clearAllMarkers()
	{
		markers.clear();
		saveMarkers();
	}

	private boolean shouldShowMarkerMenu()
	{
		if (config.markMenuMode() == TileMarkerSymbolsConfig.MarkMenuMode.SHIFT_RIGHT_CLICK)
		{
			return client.isKeyPressed(KeyCode.KC_SHIFT);
		}

		return true;
	}

	private void updateSidebarPanel()
	{
		if (navButton == null)
		{
			return;
		}

		if (config.showSidebarPanel())
		{
			addSidebarPanel();
		}
		else
		{
			removeSidebarPanel();
		}
	}

	private void addSidebarPanel()
	{
		if (navButton != null && !sidebarPanelAdded)
		{
			clientToolbar.addNavigation(navButton);
			sidebarPanelAdded = true;
		}
	}

	private void removeSidebarPanel()
	{
		if (navButton != null && sidebarPanelAdded)
		{
			clientToolbar.removeNavigation(navButton);
			sidebarPanelAdded = false;
		}
	}

	private void markTile(WorldPoint worldPoint, String label)
	{
		if (worldPoint == null)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Could not mark tile: no tile found.", null);
			return;
		}

		if (label == null || label.isEmpty())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Could not mark tile: no symbol selected.", null);
			return;
		}

		clearMarker(worldPoint);

		markers.add(new SymbolTileMarker(worldPoint, label, null));
		saveMarkers();
	}

	private void labelTile(SymbolTileMarker existingMarker)
	{
		WorldPoint worldPoint = existingMarker.getWorldPoint();
		Color color = existingMarker.getColor();
		String currentLabel = existingMarker.getLabel() == null ? "" : existingMarker.getLabel();

		SwingUtilities.invokeLater(() ->
		{
			String input = (String) JOptionPane.showInputDialog(
				null,
				"Enter symbol marker label:",
				"Symbol marker label",
				JOptionPane.PLAIN_MESSAGE,
				null,
				null,
				currentLabel
			);

			if (input != null)
			{
				updateMarker(worldPoint, input.trim(), color);
			}
		});
	}

	private void openColorPicker(SymbolTileMarker existingMarker)
	{
		Color startingColor = existingMarker.getColor();

		if (startingColor == null)
		{
			startingColor = getGroundMarkerDefaultColor();
		}

		Color finalStartingColor = startingColor;

		SwingUtilities.invokeLater(() ->
		{
			RuneliteColorPicker colorPicker = colorPickerManager.create(
				client,
				finalStartingColor,
				"Symbol tile marker color",
				false
			);

			colorPicker.setOnClose(color -> colorTile(existingMarker, color));
			colorPicker.setVisible(true);
		});
	}

	private void colorTile(SymbolTileMarker existingMarker, Color color)
	{
		updateMarker(existingMarker.getWorldPoint(), existingMarker.getLabel(), color);
	}

	private void updateMarker(WorldPoint worldPoint, String label, Color color)
	{
		clearMarker(worldPoint);
		markers.add(new SymbolTileMarker(worldPoint, label, color));
		saveMarkers();
	}

	private SymbolTileMarker getMarker(WorldPoint worldPoint)
	{
		if (worldPoint == null)
		{
			return null;
		}

		for (SymbolTileMarker marker : markers)
		{
			if (marker.getWorldPoint().equals(worldPoint))
			{
				return marker;
			}
		}

		return null;
	}

	private void clearMarker(WorldPoint worldPoint)
	{
		if (worldPoint == null)
		{
			return;
		}

		Iterator<SymbolTileMarker> iterator = markers.iterator();

		while (iterator.hasNext())
		{
			SymbolTileMarker marker = iterator.next();

			if (marker.getWorldPoint().equals(worldPoint))
			{
				iterator.remove();
			}
		}

		saveMarkers();
	}

	private Color getGroundMarkerDefaultColor()
	{
		Color color = configManager.getConfiguration(
			GROUND_MARKER_CONFIG_GROUP,
			GROUND_MARKER_COLOR_KEY,
			Color.class
		);

		if (color == null)
		{
			return DEFAULT_MARKER_COLOR;
		}

		return color;
	}

	private void loadMarkers()
	{
		markers.clear();

		String savedMarkers = config.savedMarkers();

		if (savedMarkers == null || savedMarkers.trim().isEmpty())
		{
			return;
		}

		String[] lines = savedMarkers.split("\\R");

		for (String line : lines)
		{
			String[] parts = line.split(":", -1);

			if (parts.length < 4)
			{
				continue;
			}

			try
			{
				int x = Integer.parseInt(parts[0]);
				int y = Integer.parseInt(parts[1]);
				int plane = Integer.parseInt(parts[2]);
				String label = new String(Base64.getDecoder().decode(parts[3]), StandardCharsets.UTF_8);

				Color color = null;

				if (parts.length >= 5 && parts[4] != null && !parts[4].isEmpty())
				{
					color = new Color(Integer.parseInt(parts[4]), true);
				}

				markers.add(new SymbolTileMarker(new WorldPoint(x, y, plane), label, color));
			}
			catch (Exception ignored)
			{
			}
		}
	}

	private void saveMarkers()
	{
		StringBuilder builder = new StringBuilder();

		for (SymbolTileMarker marker : markers)
		{
			WorldPoint worldPoint = marker.getWorldPoint();
			String label = marker.getLabel() == null ? "" : marker.getLabel();
			String encodedLabel = Base64.getEncoder().encodeToString(label.getBytes(StandardCharsets.UTF_8));
			String colorValue = marker.getColor() == null ? "" : Integer.toString(marker.getColor().getRGB());

			builder
				.append(worldPoint.getX())
				.append(":")
				.append(worldPoint.getY())
				.append(":")
				.append(worldPoint.getPlane())
				.append(":")
				.append(encodedLabel)
				.append(":")
				.append(colorValue)
				.append("\n");
		}

		configManager.setConfiguration(CONFIG_GROUP, SAVED_MARKERS_KEY, builder.toString());
	}

	@Provides
	TileMarkerSymbolsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TileMarkerSymbolsConfig.class);
	}

	private BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();

		graphics.setColor(Color.WHITE);
		graphics.drawString("★", 3, 13);

		graphics.dispose();
		return image;
	}
